import{c as a,Q as t,j as r,m as i}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"ChatGPT Agent System Card","description":"","frontmatter":{"url":"https://cdn.openai.com/pdf/839e66fc-602c-48bf-81d3-b21eacc3459d/chatgpt_agent_system_card.pdf","title":"ChatGPT Agent System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["OpenAI"],"domains":["system-card"],"pdf_path":"pdfs/openai-chatgpt-agent-system-card.pdf","published_date":"2025-07-17T00:00:00.000Z","source_url":"https://cdn.openai.com/pdf/839e66fc-602c-48bf-81d3-b21eacc3459d/chatgpt_agent_system_card.pdf"},"headers":[],"relativePath":"research/papers/2025-07-17-openai-chatgpt-agent-system-card.md","filePath":"research/papers/2025-07-17-openai-chatgpt-agent-system-card.md","lastUpdated":1785909234000}'),s={name:"research/papers/2025-07-17-openai-chatgpt-agent-system-card.md"};function c(n,e,o,d,p,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="chatgpt-agent-system-card" tabindex="-1">ChatGPT Agent System Card <a class="header-anchor" href="#chatgpt-agent-system-card" aria-label="Permalink to &quot;ChatGPT Agent System Card&quot;">​</a></h1><p><strong>Source</strong>: <a href="https://cdn.openai.com/pdf/839e66fc-602c-48bf-81d3-b21eacc3459d/chatgpt_agent_system_card.pdf" target="_blank" rel="noreferrer">https://cdn.openai.com/pdf/839e66fc-602c-48bf-81d3-b21eacc3459d/chatgpt_agent_system_card.pdf</a><strong>Published</strong>: July 17, 2025 <strong>PDF</strong>: <code>research/papers/pdfs/openai-chatgpt-agent-system-card.pdf</code> (42 pp, full text archived)</p><hr><h2 id="摘要-依官方-pdf-overview-與官方公開資訊整理" tabindex="-1">摘要（依官方 PDF overview 與官方公開資訊整理） <a class="header-anchor" href="#摘要-依官方-pdf-overview-與官方公開資訊整理" aria-label="Permalink to &quot;摘要（依官方 PDF overview 與官方公開資訊整理）&quot;">​</a></h2><ul><li>ChatGPT agent 是一個能自主執行任務的 agentic 系統：結合可操作的虛擬電腦（瀏覽器、終端機、檔案/API 操作），讓 ChatGPT 能代使用者完成 web browsing、研究、產出可交付成果等多步驟工作流程。</li><li>統合先前 Operator（電腦操作）與 deep research（資訊綜整）能力於單一 agentic 模型。</li><li>因賦予模型實際行動能力（real-world actions），system card 著重於新的 agentic 風險面：prompt injection、敏感操作的使用者確認、以及 Preparedness Framework 能力評估。</li></ul><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li>Agentic 模型：可在受控虛擬環境中瀏覽網頁、執行程式碼與工具、與外部網站互動以完成終端任務。</li><li>風險定位由「生成內容」擴展到「採取行動」——強調 action-space 安全。</li></ul><h3 id="關鍵能力-安全評估數字" tabindex="-1">關鍵能力 / 安全評估數字 <a class="header-anchor" href="#關鍵能力-安全評估數字" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字&quot;">​</a></h3><ul><li>Preparedness Framework：OpenAI 將 ChatGPT agent 視為在 <strong>Biological and Chemical 領域達 High capability</strong>，因而首次啟動該類別對應的強化安全防護（safeguards）與部署緩解措施。</li><li>Prompt injection 為核心 agentic 威脅：透過監控模型、訓練與產品層緩解、以及對敏感動作要求 user confirmation 來降低風險。</li><li>其他評估涵蓋 disallowed content、外部紅隊、以及對 irreversible/sensitive 操作的人為把關（具體百分比見 PDF 全文）。</li></ul><h3 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h3><ul><li>「對 sensitive/irreversible 動作要求 user confirmation」與 core.md APPLY「不可逆例外」（DELETE/DROP/prod deploy/rm -rf… 必摘要 + 等待確認）完全同構——agentic 安全的共同設計原則。</li><li>Prompt injection 緩解對應 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的 Agent Input Security（外部輸入包 <code>&lt;untrusted_objective&gt;</code>、當 data 不當 instruction）。</li><li>Bio/Chem High capability 觸發 safeguards → 對應「能力提升即提高風險、須對應 gate」的 Preparedness 思維，呼應本庫生產紅線與破壞性 gate。⚠️ 依官方公開資訊整理；數字以 PDF 全文為準。</li></ul>',13)])])}const m=a(s,[["render",c]]);export{g as __pageData,m as default};
